public(package) fun change_obligation_reward_manager_share(
    pool_reward_manager: &mut PoolRewardManager,
    obligation_id: ID,
    new_share: u64,
    clock: &Clock,
){
    update_obligation_reward_manager(pool_reward_manager, obligation_id, clock, false);

    let obligation_reward_manager = pool_reward_manager.obligation_reward_managers.borrow_mut(obligation_id);

    pool_reward_manager.total_shares = 
        pool_reward_manager.total_shares - obligation_reward_manager.share + new_share;

    obligation_reward_manager.share = new_share;
}

public(package) fun claim_rewards<CoinType>(
    pool_reward_manager: &mut PoolRewardManager,
    obligation_id: ID,
    clock: &Clock,
    reward_index: u64,
): Balance<CoinType>{
    update_obligation_reward_manager(pool_reward_manager, obligation_id, clock, false);

    let pool_reward = pool_reward_manager.pool_rewards.borrow_mut(reward_index).borrow_mut();

    assert!(pool_reward.coin_type == type_name::with_defining_ids<CoinType>(), error::liquidity_mining_invalid_type());

    let obligation_reward_manager = pool_reward_manager.obligation_reward_managers.borrow_mut(obligation_id);

    let reward_tracker = obligation_reward_manager.rewards.borrow_mut(reward_index);
    assert!(reward_tracker.is_some(), error::liquidity_mining_no_reward_to_claim());

    let reward = reward_tracker.borrow_mut();
    let claimable_rewards = reward.earned_rewards.floor();
    reward.earned_rewards = reward.earned_rewards.sub(float::from(claimable_rewards));

    let reward_balance = pool_reward.additional_fields.borrow_mut<RewardBalance<CoinType>, Balance<CoinType>>(RewardBalance<CoinType>{});

    if (clock.timestamp_ms() >= pool_reward.end_time_ms) {
        // the pool reward has ended, purge the reward at reward_index
        let ObligationReward{
            pool_reward_id: _,
            earned_rewards: _,
            cumulative_rewards_per_share: _,
        } = reward_tracker.extract();

        pool_reward.num_obligation_reward_managers = pool_reward.num_obligation_reward_managers - 1;
    };

    reward_balance.split(claimable_rewards)
}

// === Private Functions ===
fun find_available_index(
    pool_reward_manager: &mut PoolRewardManager
): u64{
    let mut i = 0;

    while (i < pool_reward_manager.pool_rewards.length()) {
        let optional_pool_reward = pool_reward_manager.pool_rewards.borrow(i);
        if (optional_pool_reward.is_none()) {
            return i
        };
        i = i + 1;
    };
    pool_reward_manager.pool_rewards.push_back(option::none());
    i
}

